methodology.probeScript:
import {readFileSync,writeFileSync} from 'node:fs';
import {spawn,spawnSync} from 'node:child_process';
import {chromium} from 'playwright';
import {PNG} from 'pngjs';
const snapshot=JSON.parse(readFileSync('out/grid-429-1966-429-1966.snapshot.json'));
const fields=snapshot.nodes['429:1966'].fields.childrenIds.map(id=>({id,...snapshot.nodes[id].fields}));
const reference=PNG.sync.read(readFileSync('out/grid-429-1966.reference.png'));
function flatten(png){for(let i=0;i<png.data.length;i+=4){let a=png.data[i+3]/255;for(let c=0;c<3;c++)png.data[i+c]=Math.round(png.data[i+c]*a+30*(1-a));png.data[i+3]=255;}return png;}
flatten(reference);
function metric(png){flatten(png);let total=0, per=fields.map(()=>0),other=0;for(let y=0;y<1086;y++)for(let x=0;x<1281;x++){let i=(y*1281+x)*4;if([0,1,2].some(c=>Math.abs(png.data[i+c]-reference.data[i+c])>24)){total++;let j=fields.findIndex(f=>x>=Math.floor(f.x)&&x<Math.ceil(f.x+f.width)&&y>=Math.floor(f.y)&&y<Math.ceil(f.y+f.height));if(j>=0)per[j]++;else other++;}}return {total,per,other};}
const preview=spawn(process.execPath,['node_modules/vite/bin/vite.js','preview','--port','4276','--strictPort'],{stdio:'ignore'});
const browser=await chromium.launch();const results={};
try{
for(let i=0;i<50;i++){try{if((await fetch('http://localhost:4276')).ok)break;}catch{} await new Promise(r=>setTimeout(r,200));}
const page=await browser.newPage({viewport:{width:1281,height:1086},deviceScaleFactor:1});
for(const mode of ['baseline','exact-size','source-position','rounded-position','natural-size','natural-source-position','compositor','natural-compositor','svg','natural-svg']){
await page.goto('http://localhost:4276/?screen=grid-429-1966',{waitUntil:'networkidle'});await page.waitForSelector('body[data-ready="1"]');await page.evaluate(()=>document.fonts.ready);
await page.evaluate(({mode,fields})=>{const imgs=[...document.images];imgs.forEach((img,i)=>{const f=fields[i];if(mode.includes('compositor'))img.style.transform='translateZ(0)';if(mode==='exact-size'){img.style.width=f.width+'px';img.style.height=f.height+'px';}if(mode==='source-position'||mode==='rounded-position'||mode==='natural-source-position'){img.style.position='absolute';img.style.left=(mode==='rounded-position'?Math.round(f.x):f.x)+'px';img.style.top=(mode==='rounded-position'?Math.round(f.y):f.y)+'px';}if(mode.startsWith('natural')){img.style.objectFit='none';img.style.objectPosition='left top';}if(mode.includes('svg')){const r=img.getBoundingClientRect();const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.style.cssText='position:absolute;left:'+r.x+'px;top:'+r.y+'px;width:'+r.width+'px;height:'+r.height+'px;overflow:hidden';const si=document.createElementNS('http://www.w3.org/2000/svg','image');si.setAttribute('href',img.src);si.setAttribute('width',mode.startsWith('natural')?img.naturalWidth:r.width);si.setAttribute('height',mode.startsWith('natural')?img.naturalHeight:r.height);si.setAttribute('preserveAspectRatio','none');svg.append(si);document.body.append(svg);img.style.visibility='hidden';}});}, {mode,fields});
const boxes=await page.evaluate(()=>({grid:(()=>{let e=document.querySelector('#root>div'),s=getComputedStyle(e),r=e.getBoundingClientRect();return {width:r.width,height:r.height,cols:s.gridTemplateColumns,rows:s.gridTemplateRows};})(),imgs:[...document.images].map(img=>{let r=img.getBoundingClientRect();return {src:img.getAttribute('src'),x:r.x,y:r.y,w:r.width,h:r.height,nw:img.naturalWidth,nh:img.naturalHeight};})}));
const bytes=await page.screenshot({omitBackground:true});writeFileSync(`out/w24-probe-${mode}.png`,bytes);results[mode]={...metric(PNG.sync.read(bytes)),...boxes};
await page.setViewportSize({width:64,height:64});
await page.goto('http://localhost:4276/?screen=keyframes-458-2021',{waitUntil:'networkidle'});await page.waitForSelector('body[data-ready="1"]');
const kp=flatten(PNG.sync.read(await page.screenshot({omitBackground:true}))),kr=flatten(PNG.sync.read(readFileSync('out/keyframes-458-2021.reference.png')));let kc=0;for(let i=0;i<kp.data.length;i+=4)if([0,1,2].some(c=>Math.abs(kp.data[i+c]-kr.data[i+c])>24))kc++;
results[mode].keyframesChanged=kc;await page.setViewportSize({width:1281,height:1086});
}
}finally{await browser.close();spawnSync('taskkill',['/PID',String(preview.pid),'/T','/F']);}
for(let i=0;i<fields.length;i++){let f=fields[i],img=PNG.sync.read(readFileSync('public'+results.baseline.imgs[i].src));flatten(img);let count=0;for(let y=0;y<img.height;y++)for(let x=0;x<img.width;x++){let a=(y*img.width+x)*4,b=((y+Math.round(f.y))*1281+x+Math.round(f.x))*4;if([0,1,2].some(c=>Math.abs(img.data[a+c]-reference.data[b+c])>24))count++;}results.baseline.imgs[i].exportAtRoundedOriginChanged=count;}
writeFileSync('out/w24-grid-probes.json',JSON.stringify(results,null,2));console.log(JSON.stringify(results,null,2));
